24	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
25	            owner.setPossibleDuplicate(false);
26	            owner.setPossibleDuplicateOf(null);
27	            return; // declared household member — not a suspected duplicate
28	        }
