30	        Owner match = null;
31	        for (Owner existing : ownerRepository.findAll()) {
32	            if (Boolean.TRUE.equals(existing.getDeleted())) {
33	                continue; // soft-deleted owners are ignored by the duplicate check
34	            }
35	            if (householdId.equals(HouseholdId.of(existing.getLastName(), existing.getPostcode()))) {
36	                if (match == null || existing.getId() < match.getId()) {
37	                    match = existing;
38	                }
39	            }
40	        }
41	        if (match != null) {
42	            owner.setPossibleDuplicate(true);
43	            owner.setPossibleDuplicateOf(match.getId());
44	        } else {
45	            owner.setPossibleDuplicate(false);
46	            owner.setPossibleDuplicateOf(null);
47	        }
48	    }
49	}
