17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
19	        String householdId = HouseholdId.of(owner.getLastName(), owner.getPostcode());
20	        int count = 1;
21	        for (Owner existing : ownerRepository.findAll()) {
22	            if (householdId.equals(HouseholdId.of(existing.getLastName(), existing.getPostcode()))) {
23	                count++;
24	            }
25	        }
26	        owner.setHouseholdSize(count);
27	    }
28	}
