1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Set;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	
9	/**
10	 * Rejects a create-owner request whose {@code email} domain is on the disposable-domain blocklist.
11	 * Email is optional, so an absent or blank value is left untouched. Runs after {@link NormalizeEmail}
12	 * has validated the syntax and lower-cased the value, so the domain is matched case-insensitively.
13	 * A blocked domain is rejected via {@link DisposableEmailDomainException}, which the global handler
14	 * turns into a 400.
15	 */
16	public class RejectDisposableEmailDomain {
17	
18	    /** Domains whose addresses are rejected. */
19	    static final Set<String> BLOCKED_DOMAINS = Set.of(
20	            "mailinator.com", "tempmail.com", "guerrillamail.com");
21	
22	    public void service(@Val OwnerFieldsDto request) throws DisposableEmailDomainException {
23	        String raw = request.getEmail();
24	        if (raw == null || raw.isBlank()) {
25	            return;
26	        }
27	        int at = raw.lastIndexOf('@');
28	        if (at < 0) {
29	            return;
30	        }
31	        String domain = raw.substring(at + 1).trim().toLowerCase(Locale.ROOT);
32	        if (BLOCKED_DOMAINS.contains(domain)) {
33	            throw new DisposableEmailDomainException(domain);
34	        }
35	    }
36	}
37

1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Thrown by {@link RejectDisposableEmailDomain} when an owner request supplies an {@code email}
5	 * whose domain is on the disposable-domain blocklist. Handled globally by
6	 * {@code DisposableEmailDomainExceptionHandler}, which responds 400.
7	 */
8	public class DisposableEmailDomainException extends Exception {
9	
10	    public DisposableEmailDomainException(String domain) {
11	        super("Email domain '" + domain + "' is a disposable-address provider and is not accepted.");
12	    }
13	}
