11	/**
12	 * First step of the create-owner pipeline. If the request carries an {@code Idempotency-Key} header
13	 * whose value already created an owner, responds with that originally created owner and {@code 200 OK}
14	 * instead of creating a duplicate. Otherwise takes the {@code proceed} branch to run the normal
15	 * create pipeline (which reads the request body). A missing or blank header always proceeds — the
16	 * header resolves to {@code null} when absent, so key-less creates are unaffected.
17	 */
18	public class CheckIdempotencyKey {
19	
20	    @FunctionalInterface
21	    public interface Proceed {
22	        void proceed();
23	    }
24	
25	    public void service(@HttpHeaderParameter("Idempotency-Key") String idempotencyKey,
26	            IdempotencyStore store, OwnerRepository ownerRepository, OwnerMapper ownerMapper,
27	            @Flow("proceed") Proceed proceed, ObjectResponse<OwnerDto> response) {
28	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
29	            Integer existingId = store.find(idempotencyKey);
30	            if (existingId != null) {
31	                Owner existing = ownerRepository.findById(existingId);
32	                if (existing != null) {
33	                    response.send(ownerMapper.toOwnerDto(existing));
34	                    return; // idempotent replay: original owner, 200 OK
35	                }
36	            }
37	        }
38	        proceed.proceed();
39	    }
40	}
